SELECT COUNT(*) AS unanswered_questions
FROM posts_questions q
WHERE NOT EXISTS (
    SELECT 1 FROM posts_answers a WHERE a.parent_id = q.post_id
);

SELECT COUNT(*) AS question_count
FROM posts_questions
WHERE creation_date >= date((SELECT MAX(creation_date) FROM posts_questions), '-6 months');

SELECT COUNT(*) AS question_count
FROM posts_questions
WHERE strftime('%Y', creation_date) = (SELECT strftime('%Y', MAX(creation_date)) FROM posts_questions);

SELECT ROUND(100.0 * SUM(CASE WHEN (julianday(a.creation_date) - julianday(q.creation_date)) * 24 <= 1 THEN 1 ELSE 0 END) / COUNT(*), 2) AS percentage_within_one_hour
FROM posts_answers a
JOIN posts_questions q ON a.parent_id = q.post_id;

SELECT COUNT(*) AS questions_without_comments
FROM posts_questions q
WHERE NOT EXISTS (
    SELECT 1 FROM comments c WHERE c.post_id = q.post_id
);
